   "coauthors": [
    "Lena Hensvik",
    "Oskar Nordström Skans"
   ],
   "contribution": "Measures worker–job match quality from multidimensional skill data. Shows that mismatch affects entry wages, wage growth and job mobility, and that it matters for learning in the labor market.",
   "confidence": "high"
  },
  {
   "title": "Optimal Unemployment Insurance in Search Equilibrium",
   "year": "2001",
   "venue": "Journal of Labor Economics",
   "coauthors": [
    "Bertil Holmlund"
   ],
   "contribution": "Shows within an equilibrium search model that benefits declining over the spell (time-limited UI) can be welfare-improving.",
   "confidence": "high"
  },
